"use client";

import Icon from "@/components/ui/Icon";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";

export default function AdminLoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const response = await fetch("/api/admin/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      const data = await response.json();

      if (response.ok && data.success) {
        router.push("/admin/register");
      } else {
        setError(data.message || "Credenciales inválidas");
      }
    } catch (err) {
      setError("Error al conectar con el servidor");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="admin-login min-h-screen flex items-center justify-center p-4 bg-linear-to-br from-burgundy/10 via-ivory to-gold/10">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="admin-login__card w-full max-w-md"
      >
        <div className="glassmorphism rounded-3xl shadow-premium p-8 border border-gold/20">
          {/* Header */}
          <div className="text-center mb-8">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-burgundy/10 mb-4">
              <Icon name="icon-user" size={32} className="text-burgundy" />
            </div>
            <h1 className="text-3xl font-serif text-burgundy mb-2">
              Admin Panel
            </h1>
            <p className="text-sm text-black/60">
              Iniciar sesión como administrador
            </p>
          </div>

          {/* Error Message */}
          {error && (
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              className="mb-6 p-4 bg-red-50 border border-red-200 rounded-xl text-red-700 text-sm"
            >
              {error}
            </motion.div>
          )}

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label
                htmlFor="email"
                className="block text-sm font-medium text-black/80 mb-2"
              >
                Email
              </label>
              <input
                id="email"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                className="w-full px-4 py-3 rounded-xl border border-black/10 bg-ivory/50 focus:outline-none focus:ring-2 focus:ring-burgundy/50 focus:border-burgundy transition-all"
                placeholder="Correo admin"
              />
            </div>

            <div>
              <label
                htmlFor="password"
                className="block text-sm font-medium text-black/80 mb-2"
              >
                Contraseña
              </label>
              <div className="relative">
                <input
                  id="password"
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  className="w-full px-4 py-3 rounded-xl border border-black/10 bg-ivory/50 focus:outline-none focus:ring-2 focus:ring-burgundy/50 focus:border-burgundy transition-all pr-12"
                  placeholder="••••••••"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-black/40 hover:text-burgundy transition-colors"
                  aria-label={
                    showPassword ? "Ocultar contraseña" : "Mostrar contraseña"
                  }
                >
                  <Icon
                    name={showPassword ? "icon-eye-off" : "icon-eye"}
                    size={20}
                  />
                </button>
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-burgundy text-ivory py-4 rounded-xl font-bold tracking-wide hover:bg-burgundy/90 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-xl shadow-burgundy/20 flex items-center justify-center gap-2"
            >
              {loading ? (
                <>
                  <div className="w-5 h-5 border-2 border-ivory/30 border-t-ivory rounded-full animate-spin"></div>
                  Verificando...
                </>
              ) : (
                <>
                  <Icon name="icon-lock" size={20} />
                  Iniciar Sesión
                </>
              )}
            </button>
          </form>

          {/* Footer */}
          <div className="mt-6 text-center">
            <a
              href="/"
              className="text-sm text-black/60 hover:text-burgundy transition-colors inline-flex items-center gap-1"
            >
              <Icon name="icon-arrow-left" size={16} />
              Volver al sitio
            </a>
          </div>
        </div>
      </motion.div>
    </div>
  );
}

"use client";

import Icon from "@/components/ui/Icon";
import UserRegistrationForm from "@/components/admin/UserRegistrationForm";
import { useRouter } from "next/navigation";

export default function AdminRegisterClient() {
  const router = useRouter();

  const handleLogout = async () => {
    await fetch("/api/admin/logout", { method: "POST" });
    router.push("/admin/login");
  };

  return (
    <div className="admin-register min-h-screen flex items-center justify-center p-4 bg-linear-to-br from-burgundy/10 via-ivory to-gold/10">
      <div className="w-full max-w-2xl">
        <div className="glassmorphism rounded-3xl shadow-premium p-8 border border-gold/20">
          {/* Header */}
          <div className="text-center mb-8">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-burgundy/10 mb-4">
              <Icon name="icon-user" size={32} className="text-burgundy" />
            </div>
            <h1 className="text-3xl font-serif text-burgundy mb-2">
              Registro Manual de Usuarios
            </h1>
            <p className="text-sm text-black/60">
              Crear nuevos usuarios en el sistema
            </p>
          </div>

          {/* Form */}
          <UserRegistrationForm />

          {/* Footer */}
          <div className="mt-8 pt-6 border-t border-black/10 flex justify-between items-center">
            <a
              href="/"
              className="text-sm text-black/60 hover:text-burgundy transition-colors inline-flex items-center gap-1"
            >
              <Icon name="icon-arrow-left" size={16} />
              Volver al sitio
            </a>
            <button
              onClick={handleLogout}
              className="text-sm text-black/60 hover:text-burgundy transition-colors inline-flex items-center gap-1"
            >
              Cerrar Sesión
              <Icon name="icon-lock" size={16} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import OrderList from "@/components/profile/OrderList";
import PageHero from "@/components/ui/PageHero";
import { auth } from "@/auth";
import { redirect } from "next/navigation";

export const metadata = {
  title: "Mi Cuenta | Tracy",
  description: "Gestiona tus pedidos y datos personales en Tracy.",
};

export default async function ProfilePage() {
  const session = await auth();

  if (!session) {
    redirect("/acceder?callbackUrl=/perfil");
  }

  const user = session.user;

  return (
    <div className="page-profile">
      <PageHero
        title={`Hola, ${user?.name || "Bienvenida"}`}
        subtitle="Aquí puedes ver el historial de tus compras y gestionar tu cuenta."
        image="/images/hero-profile.webp" // Aseguraremos que haya un fallback visual o imagen genérica
      />

      <div className="page-profile__content max-w-5xl mx-auto px-6 py-12 md:py-20 flex flex-col md:flex-row gap-12">
        {/* Sidebar / Información de Usuario (Simplificado para MVP) */}
        <aside className="page-profile__sidebar w-full md:w-1/3 shrink-0">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 sticky top-24">
            <div className="flex items-center gap-4 mb-6 pb-6 border-b border-gray-100">
              <div className="size-16 rounded-full bg-burgundy text-white flex items-center justify-center text-2xl font-serif">
                {user?.name?.[0] || "U"}
              </div>
              <div>
                <p className="font-bold text-gray-900">{user?.name}</p>
                <p className="text-sm text-gray-500 break-all">{user?.email}</p>
              </div>
            </div>

            <nav className="space-y-1">
              <button
                className="w-full text-left px-4 py-2 rounded-lg bg-burgundy/5 text-burgundy font-medium"
                aria-current="page"
              >
                Mis Pedidos
              </button>
              {/* Futuras mejoras: Direcciones, Métodos de Pago, etc. */}
              <button
                className="w-full text-left px-4 py-2 rounded-lg text-gray-600 hover:bg-gray-50 hover:text-gray-900 transition-colors opacity-50 cursor-not-allowed"
                disabled
                title="Próximamente"
              >
                Direcciones (Próximamente)
              </button>
            </nav>

            <div className="mt-8 pt-6 border-t border-gray-100">
              <a
                href="/api/auth/signout"
                className="text-sm text-red-600 hover:text-red-800 font-medium px-4"
              >
                Cerrar Sesión
              </a>
            </div>
          </div>
        </aside>

        {/* Área Principal: Lista de Órdenes */}
        <main className="page-profile__main flex-1 min-w-0">
          <OrderList />
        </main>
      </div>
    </div>
  );
}

import WooCommerceService from "@/services/WooCommerceService";
import ProductDetails from "@/components/product/ProductDetails";
import ProductReviewsClient from "@/components/product/ProductReviewsClient";
import { Metadata } from "next";
import { notFound } from "next/navigation";
import { sanitizeProductDescription } from "@/utils/sanitize";
import { MAX_DESCRIPTION_LENGTH } from "@/utils/constants";

// ISR: revalidar cada 5 minutos — los detalles de producto cambian raramente
export const revalidate = 300;

type Props = {
  params: Promise<{ slug: string }>;
};

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  const product = await WooCommerceService.getProductBySlug(slug);

  if (!product) {
    return {
      title: "Producto no encontrado | Tracy Lencería",
    };
  }

  // Detectar si es categoría Junior/Infantil basado en el nombre o descripción
  const isJunior = /junior|niña|infantil|niñas/i.test(
    product.name + (product.short_description || ""),
  );

  const seoSuffix = isJunior
    ? "Lencería Junior & Diseño Colombiano"
    : "Lencería de Autor & Diseño Colombiano Premium";

  // Usar utilidad de sanitización con longitud máxima, dejando espacio para keywords SEO
  const baseDescription = sanitizeProductDescription(
    product.short_description || product.description,
    120, // Reducir un poco para dar espacio a los sufijos SEO
  );

  const fullDescription = `${baseDescription}. ${
    isJunior ? "Lencería Junior" : "Lencería de autor"
  } con diseño colombiano premium. Hecho en Colombia con amor por Tracy.`;

  return {
    title: `${product.name} | ${seoSuffix} | Tracy`,
    description: fullDescription,
    keywords: [
      "lencería de autor",
      "diseño colombiano",
      "ropa interior premium",
      isJunior ? "lencería para niñas" : "lencería fina",
      "hecho en colombia",
      product.name.toLowerCase(),
    ],
    openGraph: {
      title: `${product.name} - Tracy Lencería`,
      description: fullDescription,
      images: product.images?.[0]?.src ? [product.images[0].src] : [],
      type: "article",
    },
    twitter: {
      card: "summary_large_image",
      title: product.name,
      description: fullDescription,
      images: product.images?.[0]?.src ? [product.images[0].src] : [],
    },
  };
}

export default async function ProductPage({ params }: Props) {
  const { slug } = await params;
  const product = await WooCommerceService.getProductBySlug(slug);

  if (!product) {
    notFound();
  }

  const reviews = await WooCommerceService.getProductReviews(product.id);

  // Crear Schema.org con descripción sanitizada
  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "Product",
    name: product.name,
    image: product.images?.map((img) => img.src) || [],
    description: sanitizeProductDescription(
      product.short_description || product.description,
    ),
    sku: product.id.toString(),
    offers: {
      "@type": "Offer",
      priceCurrency: "COP",
      price: product.price,
      availability:
        product.status === "publish"
          ? "https://schema.org/InStock"
          : "https://schema.org/OutOfStock",
      url: `https://tracylenceria.com/productos/${slug}`,
    },
  };

  return (
    <main className="main-product bg-white min-h-screen">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <ProductDetails product={product} />
      <ProductReviewsClient
        reviews={reviews}
        productId={product.id}
        productName={product.name}
      />
    </main>
  );
}

import NextAuth from "next-auth";
import Google from "next-auth/providers/google";
import Credentials from "next-auth/providers/credentials";
import WooCommerceService from "./services/WooCommerceService";

export const { handlers, signIn, signOut, auth } = NextAuth({
  providers: [
    Google,
    Credentials({
      name: "WordPress",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) return null;

        try {
          const result = await WooCommerceService.loginCustomer({
            email: credentials.email as string,
            password: credentials.password as string,
          });

          if (result.success && result.user) {
            return result.user;
          }

          return null;
        } catch (error) {
          console.error("Authorize Error:", error);
          return null;
        }
      },
    }),
  ],
  callbacks: {
    async signIn({ user, account, profile }) {
      if (account?.provider === "google") {
        if (!user.email) return false;

        try {
          // 1. Verificar si el usuario ya existe en WooCommerce
          const existingCustomer = await WooCommerceService.getCustomerByEmail(
            user.email,
          );

          if (existingCustomer) {
            // Usuario existe, permitir login
            return true;
          }

          // 2. Si no existe, crear usuario en WooCommerce
          // Generar una contraseña aleatoria fuerte (el usuario usará Google para entrar)
          const randomPassword = crypto.randomUUID() + "A!1";

          const firstName =
            profile?.given_name || user.name?.split(" ")[0] || "User";
          const lastName =
            profile?.family_name ||
            user.name?.split(" ").slice(1).join(" ") ||
            "";

          const registerResult = await WooCommerceService.registerCustomer({
            email: user.email,
            first_name: firstName,
            last_name: lastName,
            username: user.email.split("@")[0], // Username basado en email
            password: randomPassword,
          });

          if (registerResult.success) {
            return true;
          } else {
            console.error(
              "Error creating WC customer from Google Login:",
              registerResult,
            );
            return false;
          }
        } catch (error) {
          console.error("Error in Google Login flow:", error);
          return false;
        }
      }
      return true;
    },
    async jwt({ token, user, account }) {
      if (user) {
        token.id = user.id;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user && token.id) {
        session.user.id = token.id as string;
      }
      return session;
    },
  },
});

