"use client";

import { useSearchParams } from "next/navigation";
import Link from "next/link";
import ProductsGrid from "./ProductsGrid";
import ThreeRingLoader from "@/components/ui/ThreeRingLoader";
import { useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useProducts } from "@/hooks/useProducts";
import { ProductsPage, Category } from "@/services/WooCommerceService";
import { INFINITE_SCROLL_ROOT_MARGIN } from "@/utils/constants";

// 🛑 TS CORRECCIÓN: Definimos las props requeridas para la reutilización.
interface ProductsProps {
  title: string;
  basePath: string;
  initialData?: ProductsPage;
  headingLevel?: "h1" | "h2"; // Permitir nivel de encabezado dinámico
  categories?: Category[]; // Categorías para filtros
  initialPage?: number; // Página inicial para SSR
  categoryId?: number; // ID de categoría para filtrado
}

export default function Products({
  title,
  basePath,
  initialData,
  headingLevel = "h2", // Por defecto h2
  categories = [], // Por defecto array vacío
  initialPage = 1,
  categoryId,
}: ProductsProps) {
  const searchParams = useSearchParams();
  // Obtener página actual de la URL o usar la prop inicial.
  // Esto asegura que el cliente reaccione a cambios de URL incluso en soft navigation.
  const pageFromUrl = Number(searchParams.get("page")) || initialPage;

  // Construir la estructura de consulta infinita inicial si se proporcionan datos iniciales
  const infiniteInitialData = initialData
    ? {
        pages: [initialData],
        pageParams: [pageFromUrl],
      }
    : undefined;

  const {
    data,
    isLoading,
    isError,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
  } = useProducts({
    initialData: infiniteInitialData,
    page: pageFromUrl,
    categoryId, // Pass categoryId to the hook
  });

  const loadMoreRef = useRef<HTMLDivElement | null>(null);

  // Al usar paginación basada en URL, 'data.pages' solo debería tener 1 página (la actual)
  // gracias a que cambiamos la queryKey en useProducts.
  const allProducts = data?.pages.flatMap((page) => page.products) ?? [];
  const totalPages = data?.pages[0]?.totalPages ?? 1;

  // Calcular página actual
  const currentPage = pageFromUrl;

  // Detectar dirección de cambio de página para animación
  const prevPageRef = useRef(pageFromUrl);
  const direction = pageFromUrl > prevPageRef.current ? 1 : -1;
  const isFirstRender = useRef(true);

  useEffect(() => {
    prevPageRef.current = pageFromUrl;
    // El usuario solicitó eliminar el scroll automático, solo se mantiene la lógica de refs para la dirección de la animación
    if (isFirstRender.current) {
      isFirstRender.current = false;
    }
  }, [pageFromUrl]);

  // Variantes de animación para slide
  const variants = {
    enter: (direction: number) => ({
      x: direction > 0 ? 1000 : -1000,
      opacity: 0,
    }),
    center: {
      zIndex: 1,
      x: 0,
      opacity: 1,
    },
    exit: (direction: number) => ({
      zIndex: 0,
      x: direction < 0 ? 1000 : -1000,
      opacity: 0,
    }),
  };

  if (isLoading)
    return (
      <div className="page-products__status text-center py-10 flex flex-col items-center justify-center gap-3">
        <span>
          {/* @ts-ignore */}
          <ThreeRingLoader></ThreeRingLoader>
        </span>
        <span>Cargando productos...</span>
      </div>
    );
  if (isError)
    return (
      <div className="page-products__status--error text-center py-10 text-red-500">
        Error al cargar productos
      </div>
    );

  const HeadingTag = headingLevel;

  return (
    <article className="page-products" id="products-visual">
      <div className="page-products__content min-h-screen bg-transparent overflow-hidden">
        {/* 🛑 OPTIMIZACIÓN SEO 1: H1 DINÁMICO. Único y relevante para la página. */}
        <div className="page-products__header flex flex-col items-center py-8 px-4">
          <HeadingTag className="page-products__title text-2xl lg:text-4xl font-serif font-semibold lg:font-bold text-burgundy text-center mb-3 tracking-wide drop-shadow-sm">
            {title}
          </HeadingTag>
          <motion.div
            initial={{ scaleX: 0, opacity: 0 }}
            animate={{ scaleX: 1, opacity: 0.6 }}
            transition={{ duration: 0.8, delay: 0.2, ease: "easeOut" }}
            className="page-products__divider w-24 h-1 bg-golden rounded-full origin-center"
          ></motion.div>
        </div>

        <div className="page-products__grid-container relative overflow-hidden min-h-[400px]">
          <AnimatePresence initial={false} custom={direction} mode="wait">
            <motion.div
              key={pageFromUrl}
              custom={direction}
              variants={variants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{
                x: { type: "spring", stiffness: 300, damping: 30 },
                opacity: { duration: 0.2 },
              }}
              className="w-full"
            >
              <ProductsGrid products={allProducts} categories={categories} />
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Loader del Scroll Infinito (UX) - Mantener oculto si infinite scroll está desactivado logicamente */}
        <div
          ref={loadMoreRef}
          className="page-products__infinite-loader-wrapper justify-center py-8 hidden"
        >
          {/* ... */}
        </div>

        {/* 🛑 OPTIMIZACIÓN SEO 2: FALLBACK DE PAGINACIÓN RASTREABLE 🛑 */}
        {totalPages > 1 && (
          <nav
            aria-label="Paginación de productos"
            className="page-products__pagination py-6 flex justify-center space-x-2"
          >
            {[...Array(totalPages)].map((product, index) => {
              const pageNum = index + 1;
              const pageLink = `${basePath}?page=${pageNum}`;
              const isActive = pageNum === currentPage;

              const baseClasses =
                "px-4 py-2 border rounded-lg text-sm transition page-products__pagination-link";

              const stateClasses = isActive
                ? "page-products__pagination-link--active bg-burdeos text-marfil font-bold border-burdeos"
                : "bg-white text-gray-700 hover:bg-gray-100";

              return (
                <Link
                  key={pageNum}
                  href={pageLink}
                  scroll={false} // Evita scroll al top del body
                  className={`${baseClasses} ${stateClasses}`}
                >
                  {pageNum}
                </Link>
              );
            })}
          </nav>
        )}

        {!hasNextPage && totalPages > 1 && (
          <div className="page-products__end-message text-center text-gray-400 text-sm pb-10">
            No hay más productos para mostrar en este listado.
          </div>
        )}
      </div>
    </article>
  );
}

"use client";

import { useState, useRef } from "react";
import Icon from "@/components/ui/Icon";
import { submitReview } from "@/app/actions/product-actions";

interface ReviewFormProps {
  productId: number;
  productName: string;
}

export default function ReviewForm({
  productId,
  productName,
}: ReviewFormProps) {
  const [rating, setRating] = useState(0);
  const [hoverRating, setHoverRating] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [message, setMessage] = useState<{
    type: "success" | "error";
    text: string;
  } | null>(null);

  // Ref para el formulario
  const formRef = useRef<HTMLFormElement>(null);

  const handleSubmit = async (formData: FormData) => {
    setIsSubmitting(true);
    setMessage(null);

    // Validar puntuación manualmente ya que no es un input estándar
    if (rating === 0) {
      setMessage({
        type: "error",
        text: "Por favor selecciona una puntuación.",
      });
      setIsSubmitting(false);
      return;
    }

    // agregar valores manualmente
    formData.append("productId", productId.toString());
    formData.append("rating", rating.toString());

    try {
      const result = await submitReview(formData);
      if (result.success) {
        setMessage({
          type: "success",
          text: "Tu valoración ha sido enviada con éxito. Espera a que sea aprobada.",
        });
        setRating(0);
        // Reiniciar formulario de forma segura
        formRef.current?.reset();
      } else {
        setMessage({
          type: "error",
          text: result.message || "Error al enviar la valoración.",
        });
      }
    } catch (error) {
      setMessage({ type: "error", text: "Ocurrió un error inesperado." });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="review-form border border-burgundy/20 p-6 md:p-8 rounded-sm bg-ivory mt-10">
      <h3 className="text-xl font-serif text-burgundy font-medium mb-1">
        Sé el primero en valorar &ldquo;{productName}&rdquo;
      </h3>
      <p className="text-sm text-gray mb-6">
        Tu dirección de correo electrónico no será publicada. Los campos
        obligatorios están marcados con *
      </p>

      {message && (
        <div
          role="alert"
          aria-live="assertive"
          className={`p-4 mb-6 text-sm rounded ${
            message.type === "success"
              ? "bg-light-gold text-black/70"
              : "bg-burgundy/20 text-black/70"
          }`}
        >
          {message.text}
        </div>
      )}

      <form ref={formRef} action={handleSubmit} className="space-y-6">
        {/* Campo de Puntuación */}
        <div className="form-group">
          <label className="block text-sm font-medium text-black mb-2">
            Tu puntuación *
          </label>
          <div
            className="flex gap-1"
            role="radiogroup"
            aria-label="Valoración del producto"
            onMouseLeave={() => setHoverRating(0)}
          >
            {[1, 2, 3, 4, 5].map((star) => {
              const filled = (hoverRating || rating) >= star;
              return (
                <button
                  key={star}
                  type="button"
                  role="radio"
                  aria-checked={rating === star}
                  aria-label={`Puntuar ${star} estrellas`}
                  aria-setsize={5}
                  aria-posinset={star}
                  className="focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-gold transition-transform hover:scale-110"
                  onClick={() => setRating(star)}
                  onMouseEnter={() => setHoverRating(star)}
                >
                  <Icon
                    name={filled ? "icon-filled-star" : "icon-notfilled-star"}
                    size={24}
                    className={`transition-colors ${
                      filled ? "text-golden" : "text-burgundy/60"
                    }`}
                  />
                </button>
              );
            })}
          </div>
        </div>

        {/* Campo de Comentario */}
        <div className="form-group">
          <label
            htmlFor="review"
            className="block text-sm font-medium text-black mb-2"
          >
            Tu valoración *
          </label>
          <textarea
            id="review"
            name="review"
            rows={4}
            required
            className="w-full border border-black/30 px-4 py-3 focus:border-gold focus:ring-1 focus:ring-gold focus:outline-none transition-colors rounded-sm bg-ivory/20"
          ></textarea>
        </div>

        {/* Campos de Nombre y Email */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="form-group">
            <label
              htmlFor="name"
              className="block text-sm font-medium text-black mb-2"
            >
              Nombre *
            </label>
            <input
              type="text"
              id="name"
              name="name"
              required
              className="w-full border border-black/30 px-4 py-3 focus:border-gold focus:ring-1 focus:ring-gold focus:outline-none transition-colors rounded-sm bg-ivory/20"
            />
          </div>
          <div className="form-group">
            <label
              htmlFor="email"
              className="block text-sm font-medium text-black mb-2"
            >
              Correo electrónico *
            </label>
            <input
              type="email"
              id="email"
              name="email"
              required
              className="w-full border border-black/30 px-4 py-3 focus:border-gold focus:ring-1 focus:ring-gold focus:outline-none transition-colors rounded-sm bg-ivory/20"
            />
          </div>
        </div>

        {/* Casilla de Verificación */}
        <div className="form-group flex items-start gap-3">
          <input
            type="checkbox"
            id="save-info"
            name="save-info"
            className="mt-1 border-black/30 text-burgundy focus:ring-gold rounded-sm"
          />
          <label htmlFor="save-info" className="text-sm text-gray font-medium">
            Guarda mi nombre, correo electrónico y web en este navegador para la
            próxima vez que comente.
          </label>
        </div>

        {/* Botón de Envío */}
        <button
          type="submit"
          disabled={isSubmitting}
          className="px-8 py-3 border border-burgundy text-burgundy font-medium tracking-widest text-sm hover:bg-burgundy hover:text-white transition-all uppercase disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isSubmitting ? "Enviando..." : "Enviar"}
        </button>
      </form>
    </div>
  );
}

import { Order } from "@/services/WooCommerceService";
import { formatPrice } from "@/lib/utils/currency";
import Icon from "@/components/ui/Icon";
import Link from "next/link";

interface OrderCardProps {
  order: Order;
}

export default function OrderCard({ order }: OrderCardProps) {
  // Función auxiliar para determinar el color del estado
  const getStatusColor = (status: string) => {
    switch (status) {
      case "completed":
        return "text-green-600 bg-green-50 border-green-200";
      case "processing":
        return "text-blue-600 bg-blue-50 border-blue-200";
      case "pending":
      case "on-hold":
        return "text-yellow-600 bg-yellow-50 border-yellow-200";
      case "cancelled":
      case "failed":
        return "text-red-600 bg-red-50 border-red-200";
      default:
        return "text-gray-600 bg-gray-50 border-gray-200";
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case "completed":
        return "Completado";
      case "processing":
        return "Procesando";
      case "pending":
        return "Pendiente de Pago";
      case "on-hold":
        return "En Espera";
      case "cancelled":
        return "Cancelado";
      case "failed":
        return "Fallido";
      case "refunded":
        return "Reembolsado";
      default:
        return status;
    }
  };

  const statusClass = getStatusColor(order.status);
  const statusLabel = getStatusLabel(order.status);
  const date = new Date(order.date_created).toLocaleDateString("es-CO", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });

  return (
    <div className="order-card p-6 bg-white rounded-xl shadow-sm border border-gray-100 mb-4 transition-all hover:shadow-md">
      <div className="order-card__header flex flex-wrap justify-between items-start gap-4 mb-4 border-b border-gray-100 pb-4">
        <div>
          <h3 className="order-card__number text-lg font-serif text-burgundy font-bold">
